package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class AfkRecapInventoryTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private Map<Integer, Integer> inventory = new HashMap<>();
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L,
		() -> Instant.EPOCH, recaps::add, () -> inventory);

	@Before
	public void baselineXp()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			xp.put(skill, 1000);
		}
		manager.baseline(xp);
	}

	private void ticks(int count, AfkRecapConfig settings)
	{
		for (int i = 0; i < count; i++)
		{
			manager.gameTick(settings);
		}
	}

	private void gainItem(int quantity)
	{
		inventory = Collections.singletonMap(ItemID.YEW_LOGS, quantity);
		manager.inventoryChanged(inventory);
	}

	@Test
	public void focusWithOnlyItemsProducesRecapAndIsAcceptedByHistoryAndOverlay()
	{
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		assertEquals(1, recaps.size());
		AfkRecapSession recap = recaps.get(0);
		assertTrue(recap.getXpGained().isEmpty());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recap.getItemGains());
		AfkRecapHistory history = new AfkRecapHistory();
		assertTrue(history.add(recap));
		AfkRecapItemPresentation items = new AfkRecapItemPresentation(id ->
			new AfkRecapItemPresentation.ItemDetails("Yew logs", 270));
		AfkRecapController overlay = new AfkRecapController(() -> 0L);
		overlay.show(recap, true, 10, items.prepare(recap));
		assertNotNull(overlay.visiblePresentation(true));
		assertTrue(overlay.visiblePresentation(true).getXpRows().isEmpty());
		assertEquals(1, overlay.visiblePresentation(true).getItemRows().size());
	}

	@Test
	public void inventoryIsSnapshottedAtEverySessionStart()
	{
		gainItem(10); // Outside a session, no acquisitions are recorded.
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		manager.focusChanged(false, config);
		gainItem(15);
		manager.focusChanged(true, config);
		assertEquals(Integer.valueOf(2), recaps.get(0).getItemGains().get(ItemID.YEW_LOGS));
		assertEquals(Integer.valueOf(3), recaps.get(1).getItemGains().get(ItemID.YEW_LOGS));
	}

	@Test
	public void missingInventoryAtStartDoesNotCountFirstSynchronization()
	{
		inventory = null;
		manager.focusChanged(false, config);
		gainItem(100);
		manager.focusChanged(true, config);
		assertTrue(recaps.isEmpty());
		inventory = null;
		manager.focusChanged(false, config);
		gainItem(100);
		gainItem(102);
		manager.focusChanged(true, config);
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 2), recaps.get(0).getItemGains());
	}

	@Test
	public void idleWithItemsButNoQualifyingXpIsDiscarded()
	{
		ticks(10, config);
		gainItem(12);
		manager.statChanged(Skill.PRAYER, 1012);
		manager.manualInput();
		assertNull(manager.trigger());
		assertTrue(recaps.isEmpty());
		ticks(10, config);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
	}

	@Test
	public void relevantIdleIncludesBothXpAndEarlierItemGains()
	{
		ticks(10, config);
		gainItem(12);
		ticks(70, config);
		assertTrue(recaps.isEmpty());
		assertTrue(manager.relevantSkills().isEmpty());
		manager.statChanged(Skill.WOODCUTTING, 1525);
		manager.manualInput();
		assertEquals(Collections.singletonMap(Skill.WOODCUTTING, 525L), recaps.get(0).getXpGained());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recaps.get(0).getItemGains());
	}

	@Test
	public void repeatedIdleSessionsKeepSeparateAcquisitionTotals()
	{
		ticks(10, config);
		gainItem(2);
		manager.statChanged(Skill.MINING, 1010);
		manager.manualInput();
		ticks(10, config);
		gainItem(5);
		manager.statChanged(Skill.MINING, 1020);
		manager.manualInput();
		assertEquals(Integer.valueOf(2), recaps.get(0).getItemGains().get(ItemID.YEW_LOGS));
		assertEquals(Integer.valueOf(3), recaps.get(1).getItemGains().get(ItemID.YEW_LOGS));
	}

	private void assertDelayedSkillRelevance(Skill skill)
	{
		ticks(10, config);
		gainItem(12);
		ticks(90, config);
		assertTrue(manager.relevantSkills().isEmpty());
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		manager.statChanged(skill, 1050);
		assertTrue(manager.relevantSkills().contains(skill));
		manager.manualInput();
		assertEquals(Collections.singletonMap(skill, 50L), recaps.get(0).getXpGained());
		assertEquals(Collections.singletonMap(ItemID.YEW_LOGS, 12), recaps.get(0).getItemGains());
	}

	@Test
	public void sailingXpCanQualifyDelayedCandidateAndRetainsEarlierItems()
	{
		assertTrue(config.idleSailing());
		assertTrue(IdleActivity.enabledSkills(config).contains(Skill.SAILING));
		assertDelayedSkillRelevance(Skill.SAILING);
	}

	@Test
	public void slayerXpCanQualifyDelayedCandidateAndRetainsEarlierItems()
	{
		assertTrue(config.idleCombat());
		assertTrue(IdleActivity.enabledSkills(config).contains(Skill.SLAYER));
		assertDelayedSkillRelevance(Skill.SLAYER);
	}

	@Test
	public void disabledSailingDoesNotQualifyCandidate()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean idleSailing() { return false; }
		};
		assertFalse(IdleActivity.enabledSkills(disabled).contains(Skill.SAILING));
		ticks(10, disabled);
		gainItem(12);
		manager.statChanged(Skill.SAILING, 1050);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void disabledSlayerDoesNotQualifyViaSlayer()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean idleSlayer() { return false; }
		};
		assertFalse(IdleActivity.enabledSkills(disabled).contains(Skill.SLAYER));
		ticks(10, disabled);
		gainItem(12);
		manager.statChanged(Skill.SLAYER, 1050);
		manager.manualInput();
		assertTrue(recaps.isEmpty());
	}

	@Test
	public void itemGainsAreDefensiveSnapshots()
	{
		Map<Integer, Integer> gains = new HashMap<>();
		gains.put(ItemID.LOGS, 12);
		AfkRecapSession recap = new AfkRecapSession(AfkSessionTrigger.FOCUS, 0, Instant.EPOCH,
			1, Instant.EPOCH, 600, Collections.emptyMap(), Collections.emptySet(), gains);
		gains.clear();
		assertEquals(Collections.singletonMap(ItemID.LOGS, 12), recap.getItemGains());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void itemGainsAreImmutable()
	{
		manager.focusChanged(false, config);
		gainItem(12);
		manager.focusChanged(true, config);
		recaps.get(0).getItemGains().put(ItemID.COINS, 1);
	}
}

package com.afkrecap;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import org.junit.Test;
import org.slf4j.LoggerFactory;
import static org.junit.Assert.*;

public class AfkSessionManagerTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};

	private void ticks(AfkSessionManager manager, int count)
	{
		for (int i = 0; i < count; i++)
		{
			manager.gameTick(config);
		}
	}

	@Test
	public void relevantIdleSessionRearmsFromTheInputThatEndsIt()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.baseline(Collections.singletonMap(Skill.WOODCUTTING, 100));
		manager.manualInput();
		ticks(manager, 10);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		manager.statChanged(Skill.WOODCUTTING, 110);
		assertEquals(Collections.singleton(Skill.WOODCUTTING), manager.relevantSkills());

		manager.manualInput();
		assertNull(manager.trigger());
		// Continued skilling must neither reset inactivity nor keep the old session alive.
		for (int i = 0; i < 9; i++)
		{
			manager.statChanged(Skill.WOODCUTTING, 120 + i * 10);
			manager.gameTick(config);
			assertNull(manager.trigger());
		}
		ticks(manager, 1);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().isEmpty());
		manager.statChanged(Skill.WOODCUTTING, 210);
		assertEquals(Collections.singleton(Skill.WOODCUTTING), manager.relevantSkills());
	}

	@Test
	public void discardedIdleCandidateRearmsFromTheInputThatEndsIt()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.manualInput();
		ticks(manager, 10);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().isEmpty());

		manager.manualInput();
		assertNull(manager.trigger());
		ticks(manager, 9);
		assertNull(manager.trigger());
		ticks(manager, 1);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().isEmpty());
	}

	@Test
	public void idleStartsAtThresholdWithoutRecentXp()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.baseline(Collections.singletonMap(Skill.FISHING, 100));
		ticks(manager, 9);
		assertNull(manager.trigger());
		ticks(manager, 1);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().isEmpty());
		manager.statChanged(Skill.FISHING, 110);
		assertTrue(manager.relevantSkills().contains(Skill.FISHING));
		manager.manualInput();
		assertNull(manager.trigger());
	}

	@Test
	public void manualInputResetsInactivityAndEndsEmptyCandidate()
	{
		AfkSessionManager manager = new AfkSessionManager();
		ticks(manager, 9);
		manager.manualInput();
		ticks(manager, 9);
		assertNull(manager.trigger());
		ticks(manager, 1);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertTrue(manager.relevantSkills().isEmpty());
		manager.manualInput();
		assertNull(manager.trigger());
		ticks(manager, 9);
		assertNull(manager.trigger());
	}

	@Test
	public void onlyActualEnabledXpIncreasesMakeIdleRelevant()
	{
		AfkRecapConfig fishingOnly = new AfkRecapConfig()
		{
			@Override public boolean idleMining() { return false; }
		};
		AfkSessionManager manager = new AfkSessionManager();
		manager.statChanged(Skill.FISHING, 100);
		manager.statChanged(Skill.MINING, 100);
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(fishingOnly);
		}
		manager.statChanged(Skill.MINING, 110);
		manager.statChanged(Skill.FISHING, 100);
		manager.statChanged(Skill.FISHING, 90);
		assertTrue(manager.relevantSkills().isEmpty());
		manager.statChanged(Skill.FISHING, 95);
		assertEquals(Collections.singleton(Skill.FISHING), manager.relevantSkills());
	}

	@Test
	public void initialStatAndPreSessionXpAreNotActivity()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.statChanged(Skill.FISHING, 100);
		manager.statChanged(Skill.FISHING, 110);
		ticks(manager, 10);
		manager.statChanged(Skill.MINING, 100);
		assertTrue(manager.relevantSkills().isEmpty());
	}

	@Test
	public void focusDoesNotReplaceOrEndIdleCandidate()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.statChanged(Skill.WOODCUTTING, 100);
		ticks(manager, 10);
		manager.statChanged(Skill.WOODCUTTING, 110);
		manager.focusChanged(false, config);
		manager.focusChanged(true, config);
		assertEquals(AfkSessionTrigger.IDLE, manager.trigger());
		assertEquals(Collections.singleton(Skill.WOODCUTTING), manager.relevantSkills());
		manager.manualInput();
		assertNull(manager.trigger());
	}

	@Test
	public void idleAndManualInputDoNotReplaceOrEndFocusSession()
	{
		AfkSessionManager manager = new AfkSessionManager();
		manager.focusChanged(false, config);
		ticks(manager, 20);
		manager.focusChanged(false, config);
		manager.manualInput();
		assertEquals(AfkSessionTrigger.FOCUS, manager.trigger());
		manager.focusChanged(true, config);
		assertNull(manager.trigger());
		ticks(manager, 9);
		assertNull(manager.trigger());
	}

	@Test
	public void disabledTriggersDoNotStartSessions()
	{
		AfkRecapConfig disabled = new AfkRecapConfig()
		{
			@Override public boolean startOnFocusLoss() { return false; }
			@Override public boolean startOnIdle() { return false; }
		};
		AfkSessionManager manager = new AfkSessionManager();
		manager.focusChanged(false, disabled);
		for (int i = 0; i < 100; i++)
		{
			manager.gameTick(disabled);
		}
		assertNull(manager.trigger());
	}

	@Test
	public void enabledSkillsAreSnapshottedForEachCandidate()
	{
		AfkRecapConfig mutable = new AfkRecapConfig()
		{
			@Override public boolean idleFishing() { return fishingEnabled; }
		};
		AfkSessionManager manager = new AfkSessionManager();
		manager.statChanged(Skill.FISHING, 100);
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(mutable);
		}
		fishingEnabled = false;
		manager.statChanged(Skill.FISHING, 110);
		assertTrue(manager.relevantSkills().contains(Skill.FISHING));
		manager.manualInput();
		for (int i = 0; i < 10; i++)
		{
			manager.gameTick(mutable);
		}
		manager.statChanged(Skill.FISHING, 120);
		assertTrue(manager.relevantSkills().isEmpty());
		manager.reset("test shutdown");
		assertNull(manager.trigger());
	}

	@Test
	public void endLogsReportOutcomeAndElapsedTicksAndTime()
	{
		Logger logger = (Logger) LoggerFactory.getLogger(AfkSessionManager.class);
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		logger.addAppender(appender);
		try
		{
			AtomicLong now = new AtomicLong();
			AfkSessionManager manager = new AfkSessionManager(now::get);
			manager.statChanged(Skill.FISHING, 100);
			ticks(manager, 10);
			ticks(manager, 3);
			now.set(1_800_000_000L);
			manager.statChanged(Skill.FISHING, 110);
			manager.manualInput();
			String relevant = lastSessionEnd(appender);
			assertTrue(relevant.contains("trigger=IDLE"));
			assertTrue(relevant.contains("outcome=relevant"));
			assertTrue(relevant.contains("elapsedGameTicks=3, elapsedMs=1800"));
			ticks(manager, 10);
			manager.manualInput();
			String discarded = lastSessionEnd(appender);
			assertTrue(discarded.contains("outcome=discarded"));
			assertTrue(discarded.contains("skills=[]"));
		}
		finally
		{
			logger.detachAppender(appender);
			appender.stop();
		}
	}

	private String lastSessionEnd(ListAppender<ILoggingEvent> appender)
	{
		return appender.list.stream()
			.map(ILoggingEvent::getFormattedMessage)
			.filter(message -> message.startsWith("Away session ended:"))
			.reduce((previous, latest) -> latest)
			.orElseThrow(AssertionError::new);
	}

	private boolean fishingEnabled = true;
}

package com.afkrecap;

import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class ResourceContainerStateTest
{
	@Test public void bothOpenFishContainersEnableEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN)).hiddenFish());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_SACK_BARREL_OPEN)).hiddenFish());
	}
	@Test public void bothOpenLogContainersEnableEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN)).hiddenLogs());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FORESTRY_BASKET_OPEN)).hiddenLogs());
	}
	@Test public void closedContainersDoNotEnableEvidence()
	{
		ResourceContainerState state = new ResourceContainerState(Set.of(ItemID.FISH_BARREL_CLOSED,
			ItemID.FISH_SACK_BARREL_CLOSED, ItemID.LOG_BASKET_CLOSED, ItemID.FORESTRY_BASKET_CLOSED));
		assertFalse(state.hiddenFish()); assertFalse(state.hiddenLogs());
	}
	@Test public void consumingToolsDisableUncertainHiddenGains()
	{
		assertFalse(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN, ItemID.INFERNAL_HARPOON)).hiddenFish());
		assertFalse(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.INFERNAL_AXE)).hiddenLogs());
	}
	@Test public void fellingAxesAllowConfirmedLogEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.RUNE_AXE_2H)).hiddenLogs());
		assertTrue(new ResourceContainerState(Set.of(ItemID.FORESTRY_BASKET_OPEN, ItemID.DRAGON_AXE_2H)).hiddenLogs());
	}

	@Test public void transferDetectionIncludesClosedContainersButNotOrdinaryItems()
	{
		ResourceContainerState state = new ResourceContainerState(Set.of(ItemID.FISH_BARREL_CLOSED));
		assertTrue(state.hasContainer(ResourceAcquisitionMessages.Family.FISH));
		assertFalse(state.hasContainer(ResourceAcquisitionMessages.Family.LOG));
		assertFalse(new ResourceContainerState(Set.of(ItemID.OAK_LOGS)).hasContainer(ResourceAcquisitionMessages.Family.LOG));
	}

	@Test public void depletedInfernalToolsAllowEvidence()
	{
		assertTrue(new ResourceContainerState(Set.of(ItemID.FISH_BARREL_OPEN, ItemID.INFERNAL_HARPOON_EMPTY)).hiddenFish());
		assertTrue(new ResourceContainerState(Set.of(ItemID.LOG_BASKET_OPEN, ItemID.INFERNAL_AXE_EMPTY)).hiddenLogs());
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static com.afkrecap.ResourceAcquisitionMessages.Family.*;
import static org.junit.Assert.*;

public class AfkRecapWoodcuttingResourceTest
{
	private final AfkRecapConfig config = new AfkRecapConfig() {};
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private final AfkSessionManager manager = new AfkSessionManager(() -> 0L, () -> Instant.EPOCH,
		recaps::add, Collections::emptyMap);

	private void startWoodcutting()
	{
		manager.baseline(Map.of(Skill.WOODCUTTING, 1000));
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		manager.statChanged(Skill.WOODCUTTING, 1050);
	}

	private void chat(ChatMessageType type, String message, Set<Integer> items)
	{
		// The same channel/state gates used by AfkRecapPlugin.onChatMessage.
		if (ResourceAcquisitionMessages.acceptsChat(LOG, type))
		{
			ResourceContainerState storage = new ResourceContainerState(items);
			manager.acquisitionMessage(message,
				ResourceAcquisitionMessages.acceptsChat(FISH, type) && storage.hiddenFish(), storage.hiddenLogs());
		}
	}

	private void assertOakRecap()
	{
		manager.manualInput();
		assertEquals(Map.of(ItemID.OAK_LOGS, 1), recaps.get(0).getItemGains());
		assertEquals(Map.of(Skill.WOODCUTTING, 50L), recaps.get(0).getXpGained());
	}

	@Test public void normalAxeDirectToBasketRegression()
	{
		startWoodcutting();
		chat(ChatMessageType.SPAM, "You get some oak logs.", Set.of(ItemID.LOG_BASKET_OPEN, ItemID.RUNE_AXE));
