	}

	@Test public void fellingAxeInventoryAndMessageCountOnce()
	{
		startWoodcutting();
		chat(ChatMessageType.SPAM, "You get some oak logs.", Set.of(ItemID.LOG_BASKET_OPEN, ItemID.RUNE_AXE_2H));
