		start(); end(); assertTrue(recaps.isEmpty());
	}
	private void assertBoundary(GameState state)
	{
		start(); fish(); manager.gameStateChanged(state); fish();
		manager.loggedIn(Collections.emptyMap(), 99); start(); end(); assertTrue(recaps.isEmpty());
		start(); manager.inventoryChanged(Map.of(ItemID.RAW_TROUT, 1)); end();
		assertEquals(Map.of(ItemID.RAW_TROUT, 1), recaps.get(0).getItemGains());
	}
	@Test public void hiddenGainsDoNotQualifyIdleCandidate()
	{
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		fish(); manager.manualInput(); assertTrue(recaps.isEmpty());
	}
	@Test public void fishingXpRetainsHiddenAcquisitions()
	{
		manager.baseline(Map.of(Skill.FISHING, 1000));
		for (int i = 0; i < 10; i++) { manager.gameTick(config); }
		fish(); manager.statChanged(Skill.FISHING, 1050); manager.manualInput();
		assertEquals(Map.of(ItemID.RAW_TROUT, 1), recaps.get(0).getItemGains());
		assertEquals(Map.of(Skill.FISHING, 50L), recaps.get(0).getXpGained());
	}
}

package com.afkrecap;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import com.afkrecap.ResourceAcquisitionMessages.Family;

/** Session-local reconciliation. Hold one completed tick for delayed inventory/transfer events. */
final class ResourceAcquisitionTracker
{
	private final InventoryGainTracker inventory;
	private final Map<Family, Long> transferUntil = new EnumMap<>(Family.class);
	private Batch previous;
	private Batch current = new Batch();
	private long tick;
	private Integer lastResource;
	private Family lastFamily;
	private final Set<String> bonuses = new HashSet<>();

	ResourceAcquisitionTracker(Map<Integer, Integer> baseline)
	{
		inventory = new InventoryGainTracker(baseline);
	}

	void inventoryChanged(Map<Integer, Integer> snapshot)
	{
		inventory.update(snapshot, id -> ResourceAcquisitionMessages.family(id) == null)
			.forEach((id, count) ->
			{
				Family family = ResourceAcquisitionMessages.family(id);
				if (family != null && !transferring(family))
				{
					current.inventory.merge(id, count, InventoryGainTracker::addQuantities);
					current.available.merge(id, count, InventoryGainTracker::addQuantities);
				}
			});
	}

	void message(String text, boolean fishStorage, boolean logStorage)
	{
		if (text == null)
		{
			return;
		}
		Family bonus = ResourceAcquisitionMessages.bonus(text);
		if (bonus != null)
		{
			// Only an immediately preceding typed acquisition can identify this extra item.
			if (lastResource != null && lastFamily == bonus
				&& (bonus == Family.FISH ? fishStorage : logStorage) && bonuses.add(text))
			{
				current.messages.merge(lastResource, 1, InventoryGainTracker::addQuantities);
			}
			return;
		}
		clearContext();
		for (Family family : Family.values())
		{
			Integer id = ResourceAcquisitionMessages.resource(text, family);
			if (id != null && (family == Family.FISH ? fishStorage : logStorage))
			{
				current.messages.merge(id, 1, InventoryGainTracker::addQuantities);
				lastResource = id;
				lastFamily = family;
				return;
			}
		}
	}

	void transfer(Family family)
	{
		transferUntil.put(family, tick + 2);
		// Completion messages can arrive after the inventory event, including near a tick boundary.
		removeTransfers(current, family);
		if (previous != null)
		{
			removeTransfers(previous, family);
		}
		clearContext();
	}

	void gameTick()
	{
		if (previous != null)
		{
			reconcile();
			commit(previous);
		}
		previous = current;
		current = new Batch();
		tick++;
		clearContext();
	}

	Map<Integer, Integer> gains()
	{
		reconcile();
		if (previous != null)
		{
			commit(previous);
			previous = null;
		}
		commit(current);
		current = new Batch();
		clearContext();
		return inventory.gains();
	}

	private boolean transferring(Family family)
	{
		Long until = transferUntil.get(family);
		return until != null && tick <= until;
	}

	private void reconcile()
	{
		if (previous != null)
		{
			match(previous, previous);
			match(previous, current);
			match(current, previous);
		}
		match(current, current);
	}

	private void match(Batch messages, Batch additions)
	{
		messages.messages.replaceAll((id, count) ->
		{
			int available = additions.available.getOrDefault(id, 0);
			int matched = Math.min(count, available);
			additions.available.put(id, available - matched);
			// Matched evidence confirms an acquisition now; a subsequent Fill must not erase it.
			additions.inventory.computeIfPresent(id, (item, quantity) -> quantity - matched);
			inventory.addGain(id, matched);
			return count - matched;
		});
	}

	private void commit(Batch batch)
	{
		batch.inventory.forEach(inventory::addGain);
		batch.messages.forEach(inventory::addGain);
	}

	private static void removeTransfers(Batch batch, Family family)
	{
		// Keep confirmed acquisitions; discard uncertain inventory additions during a transfer.
		batch.inventory.keySet().removeIf(id -> ResourceAcquisitionMessages.family(id) == family);
		batch.available.keySet().removeIf(id -> ResourceAcquisitionMessages.family(id) == family);
	}

	private void clearContext()
	{
		lastResource = null;
		lastFamily = null;
		bonuses.clear();
	}

	private static final class Batch
	{
		private final Map<Integer, Integer> inventory = new HashMap<>();
		private final Map<Integer, Integer> available = new HashMap<>();
		private final Map<Integer, Integer> messages = new HashMap<>();
	}
}

package com.afkrecap;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntPredicate;
import net.runelite.api.Item;

/** Acquisition deltas across inventory snapshots; null means the baseline is unavailable. */
final class InventoryGainTracker
{
	private Map<Integer, Integer> previous;
	private final Map<Integer, Integer> gains = new HashMap<>();

	InventoryGainTracker(Map<Integer, Integer> baseline)
	{
		previous = baseline == null ? null : new HashMap<>(baseline);
	}

	void update(Map<Integer, Integer> current)
	{
		update(current, id -> true);
	}

	/** Return positive deltas while allowing the caller to defer selected resources. */
	Map<Integer, Integer> update(Map<Integer, Integer> current, IntPredicate countImmediately)
	{
		Map<Integer, Integer> additions = new HashMap<>();
		if (current == null)
		{
			previous = null;
			return additions;
		}
		if (previous != null)
		{
			current.forEach((id, quantity) ->
			{
				int difference = quantity - previous.getOrDefault(id, 0);
				if (difference > 0)
				{
					additions.put(id, difference);
					if (countImmediately.test(id))
					{
						addGain(id, difference);
					}
				}
			});
		}
		previous = new HashMap<>(current);
		return additions;
	}

	void addGain(int id, int quantity)
	{
		if (quantity > 0)
		{
			gains.merge(id, quantity, InventoryGainTracker::addQuantities);
		}
	}

	Map<Integer, Integer> gains()
	{
		return Collections.unmodifiableMap(new HashMap<>(gains));
	}

	static Map<Integer, Integer> totals(Item[] items)
	{
		if (items == null)
		{
			return null;
		}
		Map<Integer, Integer> quantities = new HashMap<>();
		for (Item item : items)
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), InventoryGainTracker::addQuantities);
			}
		}
		return quantities;
	}

	static int addQuantities(int first, int second)
	{
		// The recap contract uses Integer quantities; do not overflow into negative gains.
		return (int) Math.min(Integer.MAX_VALUE, (long) first + second);
	}
}

package com.afkrecap;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.Predicate;
import net.runelite.api.Skill;

// Each category declares its toggle and all XP skills that can make a candidate relevant.
enum IdleActivity
{
	FISHING(AfkRecapConfig::idleFishing, Skill.FISHING),
	MINING(AfkRecapConfig::idleMining, Skill.MINING),
	WOODCUTTING(AfkRecapConfig::idleWoodcutting, Skill.WOODCUTTING),
	SAILING(AfkRecapConfig::idleSailing, Skill.SAILING),
	COMBAT(AfkRecapConfig::idleCombat, Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE,
		Skill.RANGED, Skill.MAGIC, Skill.HITPOINTS),
	SLAYER(AfkRecapConfig::idleSlayer, Skill.SLAYER);

	private final Set<Skill> skills;
	private final Predicate<AfkRecapConfig> enabled;

	IdleActivity(Predicate<AfkRecapConfig> enabled, Skill... skills)
	{
		this.skills = EnumSet.copyOf(Arrays.asList(skills));
		this.enabled = enabled;
	}

	static Set<Skill> enabledSkills(AfkRecapConfig config)
	{
		Set<Skill> skills = EnumSet.noneOf(Skill.class);
		for (IdleActivity activity : values())
		{
			if (activity.enabled.test(config))
			{
				skills.addAll(activity.skills);
			}
		}
		return skills;
	}
}

package com.afkrecap;

public enum AfkSessionTrigger
{
	FOCUS,
	IDLE
}

package com.afkrecap;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;

/** Presentation state shared by client events and overlay rendering; no game state mutations. */
@Singleton
public final class AfkRecapController
{
	private final LongSupplier nanoTime;
	private Presentation presentation;
	private long displayedAtNanos;
	private long displayDurationNanos;

	@Inject
	public AfkRecapController()
	{
		this(System::nanoTime);
	}

	AfkRecapController(LongSupplier nanoTime)
	{
		this.nanoTime = nanoTime;
	}

	synchronized void show(AfkRecapSession recap, boolean enabled, int durationSeconds)
	{
		show(recap, enabled, durationSeconds, AfkRecapItemPresentation.empty());
	}

	synchronized void show(AfkRecapSession recap, boolean enabled, int durationSeconds,
		AfkRecapItemPresentation.Display items)
	{
		if (!enabled)
		{
			clear();
			return;
		}
		if (!recap.hasGains()
			|| (recap.getTrigger() == AfkSessionTrigger.IDLE && recap.getRelevantIdleSkills().isEmpty()))
		{
			return;
		}
		presentation = new Presentation(recap, items);
		displayedAtNanos = nanoTime.getAsLong();
		displayDurationNanos = TimeUnit.SECONDS.toNanos(Math.max(3, Math.min(60, durationSeconds)));
	}

	synchronized Presentation visiblePresentation(boolean enabled)
	{
		if (!enabled || (presentation != null
			&& nanoTime.getAsLong() - displayedAtNanos >= displayDurationNanos))
		{
			clear();
		}
		return presentation;
	}

	synchronized void clear()
	{
		presentation = null;
	}

	static String formatDuration(long elapsedMillis)
	{
		if (elapsedMillis < 60_000)
		{
			return String.format(Locale.ROOT, "%.1fs", elapsedMillis / 1000.0);
		}
		long seconds = elapsedMillis / 1000;
		return seconds / 60 + "m " + seconds % 60 + "s";
	}

	@Getter
	static final class Presentation
	{
		private final String duration;
		private final String trigger;
		private final List<XpRow> xpRows;
		private final List<AfkRecapItemPresentation.ItemRow> itemRows;
		private final String totalValue;
		private final Map<String, Integer> npcKills;
		private final String prayerUsed;
		private final String damageTaken;

		private Presentation(AfkRecapSession recap, AfkRecapItemPresentation.Display items)
		{
			damageTaken = recap.getDamageTaken() > 0 ? Long.toString(recap.getDamageTaken()) : null;
			npcKills = recap.getNpcKills();
			prayerUsed = recap.getPrayerUsed() > 0 ? Long.toString(recap.getPrayerUsed()) : null;
			itemRows = items.getRows();
			totalValue = items.getTotalValue();
			duration = formatDuration(recap.getElapsedMillis());
			trigger = recap.getTrigger() == AfkSessionTrigger.FOCUS ? "Focus" : "Idle";
			List<XpRow> rows = new ArrayList<>();
			recap.getXpGained().forEach((skill, gained) ->
			{
				if (gained > 0)
				{
					rows.add(new XpRow(skill.getName(), "+" + gained + " XP"));
				}
			});
			xpRows = Collections.unmodifiableList(rows);
		}
	}

	@Getter
	static final class XpRow
	{
		private final String skill;
		private final String gained;

		private XpRow(String skill, String gained)
		{
			this.skill = skill;
			this.gained = gained;
		}
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;

// All calls run on the client thread. No rendering or persistent storage belongs here.
@Slf4j
final class AfkSessionManager
{
	private final LongSupplier nanoTime;
	private final Supplier<Instant> timestamp;
	private final Consumer<AfkRecapSession> recapConsumer;
	private final Supplier<Map<Integer, Integer>> inventorySnapshot;
	private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
	private long gameTicks;
	private int inactiveTicks;
	private Session session;
	private Integer prayerPoints;
	private boolean ready = true;

	AfkSessionManager()
	{
		this(System::nanoTime);
	}

	AfkSessionManager(LongSupplier nanoTime)
	{
		this(nanoTime, Instant::now, recap -> {});
	}

	AfkSessionManager(LongSupplier nanoTime, Supplier<Instant> timestamp,
		Consumer<AfkRecapSession> recapConsumer)
	{
		this(nanoTime, timestamp, recapConsumer, () -> null);
	}

	AfkSessionManager(LongSupplier nanoTime, Supplier<Instant> timestamp,
		Consumer<AfkRecapSession> recapConsumer, Supplier<Map<Integer, Integer>> inventorySnapshot)
	{
		this.inventorySnapshot = inventorySnapshot;
		this.nanoTime = nanoTime;
		this.timestamp = timestamp;
		this.recapConsumer = recapConsumer;
	}

	// Login, loading, hopping and reconnecting discard unfinished data without publishing it.
	void suspend()
	{
		ready = false;
		session = null;
		inactiveTicks = 0;
		experience.clear();
		prayerPoints = null;
	}

	void gameStateChanged(GameState state)
	{
		// Even LOGGED_IN waits for the first stable game tick before accepting activity.
		suspend();
		log.debug("Recap collection suspended for game state {}", state);
	}

	void loggedIn(Map<Skill, Integer> xp, int prayer)
	{
		suspend();
		baseline(xp);
		baselinePrayer(prayer);
		ready = true;
	}

	boolean isReady()
	{
		return ready;
	}

	void playerHitsplat(Hitsplat hit)
	{
		if (session != null && PlayerDamage.isDamage(hit))
		{
			session.damageTaken += hit.getAmount();
		}
	}

	void baseline(Map<Skill, Integer> xp)
	{
		experience.clear();
		experience.putAll(xp);
	}

	void gameTick(AfkRecapConfig config)
	{
		if (!ready)
		{
			return;
		}
		if (session != null)
		{
			session.inventory.gameTick();
		}
		gameTicks++;
		inactiveTicks = Math.min(100, inactiveTicks + 1);
		int threshold = Math.max(1, Math.min(100, config.idleGameTicks()));
		if (session == null && config.startOnIdle() && inactiveTicks >= threshold)
		{
			log.debug("Idle threshold reached: {} inactive game ticks (~{} ms)", inactiveTicks, inactiveTicks * 600L);
			start(AfkSessionTrigger.IDLE, IdleActivity.enabledSkills(config));
		}
	}

	void focusChanged(boolean focused, AfkRecapConfig config)
	{
		if (!ready)
		{
			return;
		}
		if (focused)
		{
			if (trigger() == AfkSessionTrigger.FOCUS)
			{
				end("focus regained");
				inactiveTicks = 0;
			}
		}
		else if (config.startOnFocusLoss() && session == null)
		{
			start(AfkSessionTrigger.FOCUS, EnumSet.noneOf(Skill.class));
		}
	}

	void manualInput()
	{
		if (!ready)
		{
			return;
		}
		if (trigger() == AfkSessionTrigger.IDLE)
		{
			end("manual input");
		}
		// This same input begins the next inactivity period, even when it ends a session.
		inactiveTicks = 0;
	}

	void statChanged(Skill skill, int xp)
	{
		if (!ready)
		{
			return;
		}
		Integer previous = experience.put(skill, xp);
		// A missing baseline is synchronization, not a gain. Decreases rebaseline only.
		if (session == null || previous == null || xp <= previous)
		{
			return;
		}
		long gained = (long) xp - previous;
		session.xpGained.merge(skill, gained, Long::sum);
		if (trigger() == AfkSessionTrigger.IDLE && session.enabledSkills.contains(skill)
			&& session.relevantSkills.add(skill))
		{
			log.debug("IDLE session enabled skill activity detected: {} (+{} XP)", skill, gained);
		}
	}

	void baselinePrayer(int points)
	{
		prayerPoints = points;
	}

	void prayerChanged(int points)
	{
		if (!ready)
		{
			return;
		}
		if (session != null && prayerPoints != null && points < prayerPoints)
		{
			session.prayerUsed += (long) prayerPoints - points;
		}
		prayerPoints = points;
	}

	void npcDamage(Object npc, int amount, boolean mine, boolean others)
	{
		if (session != null)
		{
			session.kills.damage(npc, amount, mine, others);
		}
	}

	void npcDeath(Object npc, String name)
	{
		if (session != null)
		{
			session.kills.death(npc, name);
		}
	}

	void npcDespawned(Object npc)
	{
		if (session != null)
		{
			session.kills.despawn(npc);
		}
	}

	void inventoryChanged(Map<Integer, Integer> inventory)
	{
		if (session != null)
		{
			session.inventory.inventoryChanged(inventory);
		}
	}

	void acquisitionMessage(String message, boolean fishStorage, boolean logStorage)
	{
		if (session != null)
		{
			session.inventory.message(message, fishStorage, logStorage);
		}
	}

	void resourceTransfer(ResourceAcquisitionMessages.Family family)
	{
		if (session != null)
		{
			session.inventory.transfer(family);
		}
	}

	void reset(String reason)
	{
		if (session != null)
		{
			end(reason);
		}
		inactiveTicks = 0;
		experience.clear();
		prayerPoints = null;
	}

	AfkSessionTrigger trigger()
	{
		return session == null ? null : session.trigger;
	}

	Set<Skill> relevantSkills()
	{
		return session == null ? EnumSet.noneOf(Skill.class) : EnumSet.copyOf(session.relevantSkills);
	}

	private void start(AfkSessionTrigger trigger, Set<Skill> enabledSkills)
	{
		session = new Session(trigger, gameTicks, nanoTime.getAsLong(), timestamp.get(), enabledSkills, inventorySnapshot.get());
		log.debug("Away session started: trigger={}, gameTick={}, enabledSkills={}", trigger, gameTicks, enabledSkills);
	}

	private void end(String reason)
	{
		Session ended = session;
		session = null;
		if (ended.trigger == AfkSessionTrigger.IDLE)
		{
			// Re-arm every idle-session ending centrally, before diagnostics run.
			inactiveTicks = 0;
		}
		Instant endTimestamp = timestamp.get();
		long ticks = gameTicks - ended.startTick;
		long elapsedMillis = (nanoTime.getAsLong() - ended.startNanos) / 1_000_000L;
		String outcome = ended.trigger == AfkSessionTrigger.IDLE
			? (ended.relevantSkills.isEmpty() ? "discarded" : "relevant") : "ended";
		log.debug("Away session ended: trigger={}, reason={}, outcome={}, skills={}, elapsedGameTicks={}, elapsedMs={}",
			ended.trigger, reason, outcome, ended.relevantSkills, ticks, elapsedMillis);
		Map<Integer, Integer> itemGains = ended.inventory.gains();
		if ((!ended.xpGained.isEmpty() || !itemGains.isEmpty() || !ended.kills.totals().isEmpty()
			|| ended.prayerUsed > 0 || ended.damageTaken > 0)
			&& (ended.trigger == AfkSessionTrigger.FOCUS || !ended.relevantSkills.isEmpty()))
		{
			AfkRecapSession recap = new AfkRecapSession(ended.trigger, ended.startTick,
				ended.startTimestamp, gameTicks, endTimestamp, elapsedMillis,
				ended.xpGained, ended.relevantSkills, itemGains, ended.kills.totals(), ended.prayerUsed, ended.damageTaken);
			logRecap(recap);
			// Hand off an immutable snapshot; no session history or permanent storage.
			recapConsumer.accept(recap);
		}
	}

	private void logRecap(AfkRecapSession recap)
	{
		if (!log.isDebugEnabled())
		{
			return;
		}
		StringBuilder message = new StringBuilder("AFK Recap\nTrigger: ")
			.append(recap.getTrigger())
			.append("\nDuration: ").append(recap.getElapsedGameTicks()).append(" ticks / ")
			.append(String.format(Locale.ROOT, "%.1f", recap.getElapsedMillis() / 1000.0))
			.append(" seconds");
		if (!recap.getXpGained().isEmpty())
		{
			message.append("\nXP gained:");
		}
		recap.getXpGained().forEach((skill, gained) ->
			message.append("\n- ").append(skill.getName()).append(": ").append(gained));
		if (!recap.getItemGains().isEmpty())
		{
			message.append("\nItems gained:");
			recap.getItemGains().forEach((id, quantity) ->
				message.append("\n- Item ").append(id).append(": ").append(quantity));
		}
		log.debug("{}", message);
	}

	private static final class Session
	{
		private final AfkSessionTrigger trigger;
		private final long startTick;
		private final long startNanos;
		private final Instant startTimestamp;
		private final Map<Skill, Long> xpGained = new EnumMap<>(Skill.class);
		private final Set<Skill> enabledSkills;
		private final ResourceAcquisitionTracker inventory;
		private final NpcKillTracker kills = new NpcKillTracker();
		private long prayerUsed;
		private long damageTaken;
		private final EnumSet<Skill> relevantSkills = EnumSet.noneOf(Skill.class);

		private Session(AfkSessionTrigger trigger, long startTick, long startNanos,
			Instant startTimestamp, Set<Skill> enabledSkills, Map<Integer, Integer> inventoryBaseline)
		{
			this.trigger = trigger;
			this.startTick = startTick;
			this.startNanos = startNanos;
			this.startTimestamp = startTimestamp;
			this.inventory = new ResourceAcquisitionTracker(inventoryBaseline);
			this.enabledSkills = EnumSet.noneOf(Skill.class);
			this.enabledSkills.addAll(enabledSkills);
		}
	}
}

package com.afkrecap;

