import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "AFK Recap",
	description = "Tracks what happens while you are AFK or away from RuneLite and summarizes XP, items, combat activity, and other session data when you return."
)
public class AfkRecapPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AfkRecapConfig config;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AfkRecapOverlay overlay;

	@Inject
	private AfkRecapController recapController;

	@Inject
	private AfkRecapHistory recapHistory;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private AfkRecapItemPresentation itemPresentation;

	// Panel and navigation state are accessed only on the Swing EDT.
	private AfkRecapPanel sidePanel;
	private NavigationButton navigationButton;
	private boolean navigationAdded;

	private volatile Object recapLifecycle;

	// Input callbacks are on the AWT thread; state mutations are queued on the client thread.
	private volatile AfkSessionManager sessions;

	private final MouseAdapter mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			manualInput();
			return event;
		}
	};

	private final KeyListener keyListener = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent event)
		{
			manualInput();
		}

		@Override
		public void keyReleased(KeyEvent event)
		{
		}

		@Override
		public void keyTyped(KeyEvent event)
		{
		}
	};

	@Provides
	AfkRecapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkRecapConfig.class);
	}

	@Override
	protected void startUp()
	{
		Object lifecycle = new Object();
		recapLifecycle = lifecycle;
		recapController.clear();
		recapHistory.setLimit(config.recentRecapLimit());
		AfkSessionManager started = new AfkSessionManager(System::nanoTime, Instant::now, recap ->
		{
			if (recapLifecycle == lifecycle)
			{
				AfkRecapItemPresentation.Display items = itemPresentation.prepare(recap);
				recapController.show(recap, config.showOverlay(), config.overlayDurationSeconds(), items);
				recapHistory.add(recap);
				refreshSidePanel();
			}
		}, this::inventorySnapshot);
		started.suspend();
		sessions = started;
		clientThread.invoke(() ->
		{
			if (sessions == started && client.getGameState() == GameState.LOGGED_IN)
			{
				baselineExperience(started);
			}
		});
		mouseManager.registerMouseListener(mouseListener);
		keyManager.registerKeyListener(keyListener);
		overlayManager.add(overlay);
		updateSidePanel();
	}

	@Override
	protected void shutDown()
	{
		recapLifecycle = null;
		updateSidePanel();
		overlayManager.remove(overlay);
		recapController.clear();
		AfkSessionManager stopped = sessions;
		sessions = null;
		mouseManager.unregisterMouseListener(mouseListener);
		keyManager.unregisterKeyListener(keyListener);
		if (stopped != null)
		{
			clientThread.invoke(stopped::suspend);
		}
	}

	private void manualInput()
	{
		AfkSessionManager current = sessions;
		if (current != null)
		{
			clientThread.invoke(() ->
			{
				// Ignore callbacks belonging to a previous enable/disable cycle.
				if (sessions == current && client.getGameState() == GameState.LOGGED_IN)
				{
					current.manualInput();
				}
			});
		}
	}

	@Subscribe
	public void onFocusChanged(FocusChanged event)
	{
		log.debug("RuneLite {} focus", event.isFocused() ? "gained" : "lost");
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			current.focusChanged(event.isFocused(), config);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			if (!current.isReady())
			{
				// All login stat synchronization has been processed before this tick.
				current.loggedIn(experienceSnapshot(), client.getBoostedSkillLevel(Skill.PRAYER));
				return;
			}
			current.gameTick(config);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null && client.getGameState() == GameState.LOGGED_IN)
		{
			current.statChanged(event.getSkill(), event.getXp());
			if (event.getSkill() == Skill.PRAYER)
			{
				current.prayerChanged(event.getBoostedLevel());
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN)
		{
			Hitsplat hit = event.getHitsplat();
			if (event.getActor() != null && event.getActor() == client.getLocalPlayer())
			{
				current.playerHitsplat(hit);
			}
			else if (event.getActor() instanceof NPC && hit != null)
			{
				current.npcDamage(event.getActor(), hit.getAmount(), hit.isMine(), hit.isOthers());
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN
			&& event.getActor() instanceof NPC)
		{
			current.npcDeath(event.getActor(), event.getActor().getName());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null)
		{
			current.npcDespawned(event.getNpc());
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null && current.trigger() != null && client.getGameState() == GameState.LOGGED_IN
			&& event.getContainerId() == InventoryID.INV)
		{
			ItemContainer inventory = event.getItemContainer();
			current.inventoryChanged(inventory == null ? null : InventoryGainTracker.totals(inventory.getItems()));
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		AfkSessionManager current = sessions;
		if (current == null || current.trigger() == null || client.getGameState() != GameState.LOGGED_IN || !current.isReady())
		{
			return;
		}
		if (!ResourceAcquisitionMessages.acceptsChat(Family.LOG, event.getType()) || event.getMessage() == null)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			switch (message)
			{
				case "You empty your basket.":
				case "You empty as many logs as you can carry.":
				case "You empty your basket into the bank.":
					current.resourceTransfer(Family.LOG);
					break;
				case "You empty all of your containers into the bank.":
					current.resourceTransfer(Family.FISH);
					current.resourceTransfer(Family.LOG);
					break;
				default:
					break;
			}
		}
		if (!ResourceAcquisitionMessages.mayAcquire(message))
		{
			// Preserve bonus-context invalidation without inspecting inventory/equipment.
			current.acquisitionMessage(message, false, false);
			return;
		}
		ResourceContainerState storage = resourceContainerState();
		current.acquisitionMessage(message,
			ResourceAcquisitionMessages.acceptsChat(Family.FISH, event.getType()) && storage.hiddenFish(),
			storage.hiddenLogs());
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		AfkSessionManager current = sessions;
		if (current == null || current.trigger() == null || client.getGameState() != GameState.LOGGED_IN || !current.isReady())
		{
			return;
		}
		if (event.getMenuOption() == null || event.getMenuAction() == null)
		{
			return;
		}
		String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
		Widget widget = event.getWidget();
		Family container = widget == null ? null : ResourceAcquisitionMessages.container(widget.getItemId());
		if (container == null)
		{
			container = ResourceAcquisitionMessages.container(event.getItemId());
		}
		// Item-on-container and container-on-bank-stand transfers have different target widgets.
		switch (event.getMenuAction())
		{
			case WIDGET_TARGET_ON_WIDGET:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_NPC:
				Widget selected = client.getSelectedWidget();
				Family selectedContainer = selected == null ? null
					: ResourceAcquisitionMessages.container(selected.getItemId());
				if (container != null || selectedContainer != null)
				{
					current.resourceTransfer(container != null ? container : selectedContainer);
				}
				return;
			default:
				break;
		}
		if (container != null && (option.equals("fill") || option.startsWith("empty")))
		{
			current.resourceTransfer(container);
		}
		else if (widget != null && (option.startsWith("withdraw") || option.startsWith("deposit")
			|| option.equals("empty basket")))
		{
			// Bank buttons and the forestry equipment interface may not carry an item ID.
			ResourceContainerState storage = resourceContainerState();
			for (Family family : Family.values())
			{
				if (storage.hasContainer(family))
				{
					current.resourceTransfer(family);
				}
			}
		}
		// Check dialogs are intentionally not subscribed to: their contents are synchronization.
	}

	private ResourceContainerState resourceContainerState()
	{
		Set<Integer> items = new HashSet<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(containerId);
			if (container != null)
			{
				for (Item item : container.getItems())
				{
					if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
					{
						items.add(item.getId());
					}
				}
			}
		}
		return new ResourceContainerState(items);
	}

	private Map<Integer, Integer> inventorySnapshot()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory == null ? null : InventoryGainTracker.totals(inventory.getItems());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		AfkSessionManager current = sessions;
		if (current != null)
		{
			current.gameStateChanged(event.getGameState());
			if (event.getGameState() == GameState.LOGGED_IN)
			{
				baselineExperience(current);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("away-recap".equals(event.getGroup()) && "showOverlay".equals(event.getKey())
			&& !config.showOverlay())
		{
			recapController.clear();
		}
		if ("away-recap".equals(event.getGroup()))
		{
			if ("recentRecapLimit".equals(event.getKey()))
			{
				recapHistory.setLimit(config.recentRecapLimit());
				refreshSidePanel();
			}
			else if ("enableSidePanel".equals(event.getKey()))
			{
				updateSidePanel();
			}
		}
	}

	private void refreshSidePanel()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (recapLifecycle != null && config.enableSidePanel() && sidePanel != null)
			{
				sidePanel.refresh();
			}
		});
	}

	private void updateSidePanel()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (recapLifecycle == null || !config.enableSidePanel())
			{
				if (navigationAdded)
				{
					clientToolbar.removeNavigation(navigationButton);
					navigationAdded = false;
				}
				return;
			}
			if (sidePanel == null)
			{
				sidePanel = new AfkRecapPanel(recapHistory, itemPresentation);
				navigationButton = NavigationButton.builder()
					.tooltip("AFK Recap")
					.icon(AfkRecapPanel.navigationIcon())
					.priority(6)
					.panel(sidePanel)
					.build();
			}
			sidePanel.refresh();
			if (!navigationAdded)
			{
				clientToolbar.addNavigation(navigationButton);
				navigationAdded = true;
			}
		});
	}

	private void baselineExperience(AfkSessionManager current)
	{
		current.baseline(experienceSnapshot());
		current.baselinePrayer(client.getBoostedSkillLevel(Skill.PRAYER));
	}

	private Map<Skill, Integer> experienceSnapshot()
	{
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			xp.put(skill, client.getSkillExperience(skill));
		}
		return xp;
	}
}

package com.afkrecap;

import java.util.Set;
import net.runelite.api.gameval.ItemID;

/** Small inventory/equipment snapshot, never estimated container contents. */
final class ResourceContainerState
{
	private final Set<Integer> items;

	ResourceContainerState(Set<Integer> items)
	{
		this.items = items;
	}

	boolean hasContainer(ResourceAcquisitionMessages.Family family)
	{
		return items.stream().anyMatch(id -> ResourceAcquisitionMessages.container(id) == family);
	}

	boolean hiddenFish()
	{
		return (items.contains(ItemID.FISH_BARREL_OPEN) || items.contains(ItemID.FISH_SACK_BARREL_OPEN))
			&& !items.contains(ItemID.INFERNAL_HARPOON);
	}

	boolean hiddenLogs()
	{
		// Felling ration/XP-only messages are not acquisitions. Typed log messages still are.
		return (items.contains(ItemID.LOG_BASKET_OPEN) || items.contains(ItemID.FORESTRY_BASKET_OPEN))
			&& !items.contains(ItemID.INFERNAL_AXE);
	}
}

package com.afkrecap;

import java.util.IdentityHashMap;
import java.util.Map;
import java.util.TreeMap;

/** Session-local evidence; NPC object identity avoids index reuse and morph issues. */
final class NpcKillTracker
{
	private final Map<Object, Evidence> evidence = new IdentityHashMap<>();
	private final Map<String, Integer> totals = new TreeMap<>();

	void damage(Object npc, int amount, boolean mine, boolean others)
	{
		if (npc == null || amount <= 0 || (!mine && !others))
		{
			return;
		}
		Evidence hit = evidence.computeIfAbsent(npc, ignored -> new Evidence());
		hit.mine |= mine;
		hit.others |= others;
	}

	void death(Object npc, String name)
	{
		Evidence hit = evidence.get(npc);
		if (hit == null || hit.dead)
		{
			return;
		}
		hit.dead = true;
		if (hit.mine && !hit.others && name != null && !name.trim().isEmpty())
		{
			totals.merge(name, 1, (count, added) -> count == Integer.MAX_VALUE ? count : count + added);
		}
	}

	void despawn(Object npc)
	{
		evidence.remove(npc);
	}

	Map<String, Integer> totals()
	{
		return totals;
	}

	private static final class Evidence
	{
		private boolean mine;
		private boolean others;
		private boolean dead;
	}
}

package com.afkrecap;

import java.awt.BorderLayout;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

public final class AfkRecapPanel extends PluginPanel
{
	private final AfkRecapHistory history;
	private final AfkRecapItemPresentation itemPresentation;
	private final JPanel entries = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JButton clearHistory = new JButton("Clear History");

	AfkRecapPanel(AfkRecapHistory history, AfkRecapItemPresentation itemPresentation)
	{
		this.history = history;
		this.itemPresentation = itemPresentation;
		setLayout(new BorderLayout(0, 8));
		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		JLabel title = new JLabel("AFK Recap");
		title.setForeground(ColorScheme.BRAND_ORANGE);
		header.add(title, BorderLayout.NORTH);
		header.add(clearHistory, BorderLayout.SOUTH);
		clearHistory.addActionListener(event ->
		{
			history.clear();
			refresh();
		});
		entries.setOpaque(false);
		add(header, BorderLayout.NORTH);
		add(entries, BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		assert SwingUtilities.isEventDispatchThread();
		List<AfkRecapSession> recaps = history.snapshot();
		entries.removeAll();
		clearHistory.setEnabled(!recaps.isEmpty());
		if (recaps.isEmpty())
		{
			JLabel empty = new JLabel("No completed recaps yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			entries.add(empty);
		}
		else
		{
			for (AfkRecapSession recap : recaps)
			{
				entries.add(entry(recap));
			}
		}
		entries.revalidate();
		entries.repaint();
	}

	private JPanel entry(AfkRecapSession recap)
	{
		JPanel card = new JPanel(new BorderLayout(0, 5));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		JLabel heading = new JLabel(AfkRecapPanelPresentation.header(recap, ZoneId.systemDefault()));
		heading.setForeground(ColorScheme.TEXT_COLOR);
		card.add(heading, BorderLayout.NORTH);
		JPanel xpRows = new JPanel(new GridLayout(0, 1, 0, 2));
		xpRows.setOpaque(false);
		recap.getXpGained().forEach((skill, gained) ->
		{
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			row.add(new JLabel(skill.getName()), BorderLayout.WEST);
			row.add(new JLabel(AfkRecapPanelPresentation.xp(gained)), BorderLayout.EAST);
			xpRows.add(row);
		});
		if (!recap.getNpcKills().isEmpty())
		{
			xpRows.add(new JLabel("Kills"));
			recap.getNpcKills().forEach((name, count) ->
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				row.add(new JLabel(name), BorderLayout.CENTER);
				row.add(new JLabel(count.toString()), BorderLayout.EAST);
				xpRows.add(row);
			});
		}
		if (recap.getPrayerUsed() > 0)
		{
			xpRows.add(new JLabel("Prayer used: " + recap.getPrayerUsed()));
		}

		if (recap.getDamageTaken() > 0)
		{
			xpRows.add(new JLabel("Damage taken: " + recap.getDamageTaken()));
		}

		AfkRecapItemPresentation.Display items = itemPresentation.get(recap);
		if (!items.getRows().isEmpty())
		{
			JLabel itemHeading = new JLabel("Items gained");
			itemHeading.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			xpRows.add(itemHeading);
			for (AfkRecapItemPresentation.ItemRow item : items.getRows())
			{
				JPanel row = new JPanel(new BorderLayout(6, 0));
				row.setOpaque(false);
				JLabel name = new JLabel(item.getName());
				name.setToolTipText(item.getName());
				row.add(name, BorderLayout.CENTER);
				row.add(new JLabel(item.getQuantityAndValue()), BorderLayout.EAST);
				xpRows.add(row);
			}
			if (items.getTotalValue() != null)
			{
				JPanel total = new JPanel(new BorderLayout(6, 0));
				total.setOpaque(false);
				total.add(new JLabel("Total value:"), BorderLayout.WEST);
				total.add(new JLabel(items.getTotalValue()), BorderLayout.EAST);
				xpRows.add(total);
			}
		}
		card.add(xpRows, BorderLayout.CENTER);
		return card;
	}

	static BufferedImage navigationIcon()
	{
		// Small code-drawn clock icon; no file I/O or large raster asset.
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setColor(ColorScheme.BRAND_ORANGE);
			graphics.drawOval(1, 1, 13, 13);
			graphics.drawLine(8, 4, 8, 8);
			graphics.drawLine(8, 8, 11, 10);
		}
		finally
		{
			graphics.dispose();
		}
		return icon;
	}
}

package com.afkrecap;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;

/** A deliberately small vocabulary: no XP inference, Check text, or generic success messages. */
final class ResourceAcquisitionMessages
{
	enum Family { FISH, LOG }

	private static final Pattern CATCH = Pattern.compile("^You catch (?:a|an|some)(?: raw)? ([A-Za-z ]+)[.!]$");
	// Mirror RuneLite 1.13.1 WoodcuttingPlugin's acquisition pattern; capture the item name.
	private static final Pattern CHOP = Pattern.compile("^You get (?:some|an)([\\w ]+(?:logs?|mushrooms))\\.$");
	private static final Map<String, Integer> FISH = fish();
	private static final Map<String, Integer> LOGS = logs();

	private ResourceAcquisitionMessages()
	{
	}

	/** Cheap prefilter only; the exact parser still decides whether an item can be credited. */
	static boolean mayAcquire(String message)
	{
		return message != null && (message.startsWith("You catch ") || message.startsWith("You get ")
			|| bonus(message) != null);
	}

	static boolean acceptsChat(Family family, ChatMessageType type)
	{
		return type == ChatMessageType.SPAM || (family == Family.LOG
			&& (type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.MESBOX));
	}

	static Integer resource(String message, Family family)
	{
		if (message == null)
		{
			return null;
		}
		Matcher match = (family == Family.FISH ? CATCH : CHOP).matcher(message);
		return match.matches() ? (family == Family.FISH ? FISH : LOGS)
			.get(match.group(1).trim().toLowerCase(Locale.ROOT)) : null;
	}

	static Family family(int id)
	{
		return FISH.containsValue(id) ? Family.FISH : LOGS.containsValue(id) ? Family.LOG : null;
	}

	static Family container(int id)
	{
		switch (id)
		{
			case ItemID.FISH_BARREL_OPEN:
			case ItemID.FISH_BARREL_CLOSED:
			case ItemID.FISH_SACK_BARREL_OPEN:
			case ItemID.FISH_SACK_BARREL_CLOSED:
				return Family.FISH;
			case ItemID.LOG_BASKET_OPEN:
			case ItemID.LOG_BASKET_CLOSED:
			case ItemID.FORESTRY_BASKET_OPEN:
			case ItemID.FORESTRY_BASKET_CLOSED:
				return Family.LOG;
			default:
				return null;
		}
	}

	static Family bonus(String message)
	{
		switch (message)
		{
			case "Rada's blessing enabled you to catch an extra fish.":
			case "The spirit flakes enabled you to catch an extra fish.":
				return Family.FISH;
			case "Your Kandarin headgear provides you with an additional log.":
			case "The nature offerings enabled you to chop an extra log.":
				return Family.LOG;
			default:
				return null;
		}
	}

	private static Map<String, Integer> fish()
	{
		Map<String, Integer> ids = new HashMap<>();
		ids.put("shrimp", ItemID.RAW_SHRIMP);
		ids.put("shrimps", ItemID.RAW_SHRIMP);
		ids.put("sardine", ItemID.RAW_SARDINE);
		ids.put("herring", ItemID.RAW_HERRING);
		ids.put("anchovies", ItemID.RAW_ANCHOVIES);
		ids.put("mackerel", ItemID.RAW_MACKEREL);
		ids.put("trout", ItemID.RAW_TROUT);
		ids.put("cod", ItemID.RAW_COD);
		ids.put("pike", ItemID.RAW_PIKE);
		ids.put("salmon", ItemID.RAW_SALMON);
		ids.put("tuna", ItemID.RAW_TUNA);
		ids.put("lobster", ItemID.RAW_LOBSTER);
		ids.put("bass", ItemID.RAW_BASS);
		ids.put("swordfish", ItemID.RAW_SWORDFISH);
		ids.put("monkfish", ItemID.RAW_MONKFISH);
		ids.put("karambwan", ItemID.TBWT_RAW_KARAMBWAN);
		ids.put("shark", ItemID.RAW_SHARK);
		ids.put("anglerfish", ItemID.RAW_ANGLERFISH);
		ids.put("dark crab", ItemID.RAW_DARK_CRAB);
		return Collections.unmodifiableMap(ids);
	}

	private static Map<String, Integer> logs()
	{
		Map<String, Integer> ids = new HashMap<>();
		ids.put("logs", ItemID.LOGS);
		ids.put("achey tree logs", ItemID.ACHEY_TREE_LOGS);
		ids.put("oak logs", ItemID.OAK_LOGS);
		ids.put("willow logs", ItemID.WILLOW_LOGS);
		ids.put("teak logs", ItemID.TEAK_LOGS);
		ids.put("maple logs", ItemID.MAPLE_LOGS);
		ids.put("mahogany logs", ItemID.MAHOGANY_LOGS);
		ids.put("arctic pine logs", ItemID.ARCTIC_PINE_LOG);
		ids.put("yew logs", ItemID.YEW_LOGS);
		ids.put("magic logs", ItemID.MAGIC_LOGS);
		ids.put("redwood logs", ItemID.REDWOOD_LOGS);
		new HashMap<>(ids).forEach((name, id) -> ids.put(name.substring(0, name.length() - 1), id));
		return Collections.unmodifiableMap(ids);
	}
}

package com.afkrecap;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.function.IntFunction;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

/** Resolve on the client thread once; UI code only reads immutable cached presentation data. */
@Singleton
@Slf4j
public final class AfkRecapItemPresentation
{
	private static final Display EMPTY = new Display(Collections.emptyList(), null);
	private final IntFunction<ItemDetails> lookup;
	// Values never reference the key: presentations live only as long as history/overlay need them.
	private final Map<AfkRecapSession, Display> cache = new WeakHashMap<>();

	@Inject
	AfkRecapItemPresentation(ItemManager itemManager)
	{
		this(id ->
		{
			ItemComposition definition = itemManager.getItemComposition(id);
			String name = definition == null ? null : definition.getName();
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
			{
				return new ItemDetails(null, 0);
			}
			long price = 0;
			try
			{
				price = itemManager.getItemPrice(id);
			}
			catch (RuntimeException exception)
			{
				log.debug("Unable to price recap item {}", id, exception);
			}
			return new ItemDetails(name, price);
		});
	}

	AfkRecapItemPresentation(IntFunction<ItemDetails> lookup)
	{
		this.lookup = lookup;
	}

	synchronized Display prepare(AfkRecapSession recap)
	{
		if (recap.getItemGains().isEmpty())
		{
			return EMPTY;
		}
		Display cached = cache.get(recap);
		if (cached != null)
		{
			return cached;
		}
		List<ItemRow> rows = new ArrayList<>();
		BigInteger total = BigInteger.ZERO;
		boolean priced = false;
		for (Map.Entry<Integer, Integer> entry : recap.getItemGains().entrySet())
		{
			int id = entry.getKey();
			ItemDetails details;
			try
			{
				details = lookup.apply(id);
			}
			catch (RuntimeException exception)
			{
				log.debug("Unable to resolve recap item {}", id, exception);
				details = null;
			}
			String name = details == null ? null : details.name;
			if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
			{
				name = "Item " + id;
			}
			String value = null;
			if (details != null && details.unitPrice > 0)
			{
				BigInteger itemValue = BigInteger.valueOf(details.unitPrice)
					.multiply(BigInteger.valueOf(entry.getValue()));
				total = total.add(itemValue);
				value = gp(itemValue);
				priced = true;
			}
			rows.add(new ItemRow(name, String.format(Locale.US, "%,d", entry.getValue()), value));
		}
		Display display = new Display(rows, priced ? gp(total) : null);
		cache.put(recap, display);
		return display;
	}

	synchronized Display get(AfkRecapSession recap)
	{
		return cache.getOrDefault(recap, EMPTY);
	}

	static Display empty()
	{
		return EMPTY;
	}

	private static String gp(BigInteger value)
	{
		return String.format(Locale.US, "%,d gp", value);
	}

	static final class ItemDetails
	{
		private final String name;
		private final long unitPrice;

		ItemDetails(String name, long unitPrice)
		{
			this.name = name;
			this.unitPrice = unitPrice;
		}
	}

	@Getter
	static final class Display
	{
		private final List<ItemRow> rows;
		private final String totalValue;

		private Display(List<ItemRow> rows, String totalValue)
		{
			this.rows = Collections.unmodifiableList(new ArrayList<>(rows));
			this.totalValue = totalValue;
		}
	}

	@Getter
	static final class ItemRow
	{
		private final String name;
		private final String quantity;
		private final String value;
		private final String quantityAndValue;

		private ItemRow(String name, String quantity, String value)
		{
			this.name = name;
			this.quantity = quantity;
			this.value = value;
			this.quantityAndValue = quantity + (value == null ? "" : "  " + value);
		}
	}
}

package com.afkrecap;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
public final class AfkRecapOverlay extends OverlayPanel
{
	private final AfkRecapConfig config;
	private final AfkRecapController controller;

	@Inject
	AfkRecapOverlay(AfkRecapPlugin plugin, AfkRecapConfig config, AfkRecapController controller)
	{
		super(plugin);
		this.config = config;
		this.controller = controller;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(220, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		AfkRecapController.Presentation recap = controller.visiblePresentation(config.showOverlay());
		if (recap == null)
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("AFK Recap").color(Color.YELLOW).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Away:").right(recap.getDuration()).build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Trigger:").right(recap.getTrigger()).build());
		if (!recap.getXpRows().isEmpty())
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("XP gained").build());
		}
		for (AfkRecapController.XpRow row : recap.getXpRows())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(row.getSkill()).right(row.getGained()).build());
		}
		if (!recap.getNpcKills().isEmpty())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Kills").build());
			recap.getNpcKills().forEach((name, count) -> panelComponent.getChildren().add(
				LineComponent.builder().left(name).right(count.toString()).build()));
		}
		if (recap.getPrayerUsed() != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Prayer used:").right(recap.getPrayerUsed()).build());
		}

		if (recap.getDamageTaken() != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Damage taken:").right(recap.getDamageTaken()).build());
		}

		if (!recap.getItemRows().isEmpty())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("Items gained").build());
			for (AfkRecapItemPresentation.ItemRow row : recap.getItemRows())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(row.getName()).right(row.getQuantityAndValue()).build());
			}
			if (recap.getTotalValue() != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Total value:").right(recap.getTotalValue()).build());
			}
		}
		return super.render(graphics);
	}
}

package com.afkrecap;

import java.time.Instant;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import lombok.Getter;
import net.runelite.api.Skill;

/** Immutable completed-session data, independent of logging and rendering. */
@Getter
public final class AfkRecapSession
{
	private final AfkSessionTrigger trigger;
	private final long startGameTick;
	private final Instant startTimestamp;
	private final long endGameTick;
	private final Instant endTimestamp;
	private final long elapsedMillis;
	private final Map<Skill, Long> xpGained;
	private final Set<Skill> relevantIdleSkills;
	private final Map<Integer, Integer> itemGains;
	private final Map<String, Integer> npcKills;
	private final long prayerUsed;
	private final long damageTaken;

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, Collections.emptyMap());
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, Collections.emptyMap(), 0);
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed)
	{
		this(trigger, startGameTick, startTimestamp, endGameTick, endTimestamp, elapsedMillis,
			xpGained, relevantIdleSkills, itemGains, npcKills, prayerUsed, 0);
	}

	AfkRecapSession(AfkSessionTrigger trigger, long startGameTick, Instant startTimestamp,
		long endGameTick, Instant endTimestamp, long elapsedMillis,
		Map<Skill, Long> xpGained, Set<Skill> relevantIdleSkills, Map<Integer, Integer> itemGains,
		Map<String, Integer> npcKills, long prayerUsed, long damageTaken)
	{
		this.damageTaken = Math.max(0, damageTaken);
		Map<String, Integer> kills = new TreeMap<>();
		npcKills.forEach((name, count) ->
		{
			if (name != null && !name.trim().isEmpty() && count > 0)
			{
				kills.put(name, count);
			}
		});
		this.npcKills = Collections.unmodifiableMap(kills);
		this.prayerUsed = Math.max(0, prayerUsed);
		this.trigger = trigger;
		this.startGameTick = startGameTick;
		this.startTimestamp = startTimestamp;
		this.endGameTick = endGameTick;
		this.endTimestamp = endTimestamp;
		// Use monotonic elapsed time independently of wall-clock timestamp adjustments.
		this.elapsedMillis = Math.max(0, elapsedMillis);
		EnumMap<Skill, Long> xp = new EnumMap<>(Skill.class);
		xpGained.forEach((skill, gained) ->
		{
			if (gained > 0)
			{
				xp.put(skill, gained);
			}
		});
		this.xpGained = Collections.unmodifiableMap(xp);
		EnumSet<Skill> relevant = EnumSet.noneOf(Skill.class);
		relevant.addAll(relevantIdleSkills);
		this.relevantIdleSkills = Collections.unmodifiableSet(relevant);
		Map<Integer, Integer> items = new TreeMap<>();
		itemGains.forEach((id, quantity) ->
		{
			if (id >= 0 && quantity > 0)
			{
				items.put(id, quantity);
			}
		});
		this.itemGains = Collections.unmodifiableMap(items);
	}

	public boolean hasGains()
	{
		return !xpGained.isEmpty() || !itemGains.isEmpty() || !npcKills.isEmpty() || prayerUsed > 0 || damageTaken > 0;
	}

	public long getElapsedGameTicks()
	{
		return endGameTick - startGameTick;
	}
}

package com.afkrecap;

import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;

/** Explicit HP-damage types from the installed API; resource drains are not HP damage. */
final class PlayerDamage
{
	private PlayerDamage()
	{
	}

	static boolean isDamage(Hitsplat hit)
	{
		if (hit == null || hit.getAmount() <= 0)
		{
			return false;
		}
		switch (hit.getHitsplatType())
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_OTHER_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_OTHER_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_OTHER_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_OTHER_WHITE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.BLEED:
			case HitsplatID.BURN:
				return true;
			default:
				return false;
		}
	}
}

package com.afkrecap;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import javax.inject.Singleton;

/** Bounded, in-memory completed recap history, independent of panel visibility and Swing. */
@Singleton
public final class AfkRecapHistory
{
	private final List<AfkRecapSession> recaps = new ArrayList<>();
	private int limit = 20;

	synchronized boolean add(AfkRecapSession recap)
	{
		if (!recap.hasGains()
			|| (recap.getTrigger() == AfkSessionTrigger.IDLE && recap.getRelevantIdleSkills().isEmpty()))
		{
			return false;
		}
		recaps.add(0, recap);
		// Stable sort keeps the newest arrival first when completion timestamps tie.
		recaps.sort(Comparator.comparing(AfkRecapSession::getEndTimestamp).reversed());
		trim();
		return true;
	}

	synchronized void setLimit(int limit)
	{
		this.limit = Math.max(1, Math.min(100, limit));
		trim();
	}

	synchronized List<AfkRecapSession> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(recaps));
	}

	synchronized void clear()
	{
		recaps.clear();
	}

	private void trim()
	{
		if (recaps.size() > limit)
		{
			recaps.subList(limit, recaps.size()).clear();
		}
	}
}

package com.afkrecap;

import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

final class AfkRecapPanelPresentation
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm");

	private AfkRecapPanelPresentation()
	{
	}

	static String header(AfkRecapSession recap, ZoneId zone)
	{
		String trigger = recap.getTrigger() == AfkSessionTrigger.FOCUS ? "Focus" : "Idle";
		long seconds = recap.getElapsedMillis() / 1000;
		String duration = seconds < 60 ? AfkRecapController.formatDuration(recap.getElapsedMillis())
			: String.format(Locale.ROOT, "%dm %02ds", seconds / 60, seconds % 60);
		return TIME.format(recap.getEndTimestamp().atZone(zone)) + " — " + trigger + " — " + duration;
	}

	static String xp(long gained)
	{
		return String.format(Locale.US, "+%,d XP", gained);
	}
}

